    {
      "category": "other",
      "components": ["FCC1", "NAVC1"],
      "pins": ["FCC1.48", "FCC1.73", "NAVC1.31", "NAVC1.47"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC", "I2C3_SDA_NAVC", "UART3_TX_NAVC"],
      "observed": "The STM32H753 VCAP pins on FCC1 are connected to UART3_TX_FCC and UART3_RX_FCC. The STM32F405 VCAP_1 and VCAP_2 pins on NAVC1 are connected to I2C3_SDA_NAVC and UART3_TX_NAVC. No VCAP capacitors are shown.",
      "expected": "The MCUs' VCAP pins should be connected to the external capacitors required by their datasheets, not used as signal or interface pins.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC1: pin 48 VCAP — UART3_TX_FCC; pin 73 VCAP — UART3_RX_FCC. No VCAP capacitors shown. (Flight Control Computer, page 2/6)"
        },
        {
          "source": "schematic",
          "quote": "NAVC1: VCAP_1 — I2C3_SDA_NAVC; VCAP_2 — UART3_TX_NAVC. No VCAP capacitors shown. (Navigation Computer, page 3/6)"
        },
        {
          "source": "spec",
          "quote": "Flight Control Computer MCU: STM32H753VITx; Navigation Computer MCU: STM32F405RGTx. (Component Table, Hades)"
        }
      ],
      "impact": "The MCU internal core regulators may not operate correctly without their required VCAP capacitors. The signal connections also misuse pins that are not general-purpose UART or I2C pins, so the associated interfaces will not function as intended.",
      "confidence": 0.99
    }
  ],
  "summary": "Both MCUs have their VCAP regulator pins assigned to signal nets, with no required VCAP capacitors shown. This is a serious power-design fault that can prevent reliable MCU operation and disables the affected interfaces."
}

